15	// View renders the UI
16	func (m Model) View() string {
17		// Show confirm modal if active
18		if m.confirmModal != nil {
19			return lipgloss.Place(
20				m.width, m.height,
21				lipgloss.Center, lipgloss.Center,
22				m.confirmModal.View(),
23				lipgloss.WithWhitespaceBackground(theme.ColorBackground),
24			)
25		}
26	
27		switch m.state {
28		case StateInput:
29			return m.renderInputView()
30		case StateScanning:
31			return m.renderScanningView()
32		case StateResults:
33			return m.renderResultsView()
34		case StateDetails:
35			return m.renderDetailsView()
36		}
37		return ""
38	}
39	
40	// The two columns are built as independent lists of lines and only zipped
41	// together at the end, so the spacing of one is invisible in the other's
42	// rendering — "Scan Options" ran straight into its first checkbox for as long
43	// as it did because the line below it on screen belongs to the right column.
44	// Each column is therefore built where it can be read, and checked, on its own.
45	
46	// formLeftColumn builds the target and scan-option lines.
47	func (m Model) formLeftColumn() []string {
48		return []string{
49			theme.SubTitleStyle.Render(theme.IconTarget + " Target"),
50			"",
51			m.renderTargetTypeField(),
52			m.renderTargetPathField(),
53			"",
54			theme.SubTitleStyle.Render(theme.IconConfig + " Scan Options"),
55			"",
56			m.renderCheckbox(m.enableVuln, "Vulnerability Scan (Trivy)", 2),
57			m.renderCheckbox(m.enableSecret, "Secret Scan (Gitleaks)", 3),
58			m.renderCheckbox(m.enableMisconfig, "Misconfig Scan (Trivy)", 4),
59			m.renderCheckbox(m.enableLicense, "License Scan (Trivy)", 5),
60			m.renderCheckbox(m.generateSBOM, "Generate SBOM (CycloneDX)", 6),
61		}
62	}
63	
64	// formRightColumn builds the per-tool option lines.
65	func (m Model) formRightColumn() []string {
66		right := []string{
67			theme.SubTitleStyle.Render(theme.IconConfig + " Trivy Options"),
68			"",
69			m.renderAdvancedTextInput(theme.IconServer+" Server ", m.trivyServerInput, 7),
70		}
71		if m.isServerMode() {
72			right = append(right, theme.DimStyle.Render("  Server mode: misconfig, license, SBOM unavailable"))
73		}
74		return append(right,
75			m.renderCheckbox(m.ignoreUnfixed, "Ignore Unfixed", 8),
76			m.renderCheckbox(m.ignoreEOL, "Ignore EOL", 9),
77			"",
78			theme.SubTitleStyle.Render(theme.IconConfig+" Gitleaks Options"),
79			"",
80			m.renderAdvancedTextInput(theme.IconToml+" Config ", m.gitleaksConfigInput, 10),
81			m.renderCheckbox(m.gitleaksHistory, "Scan Git History", 11),
82		)
83	}
84	
85	// renderInputView renders the form in a 2-column layout with padding
86	func (m Model) renderInputView() string {
87		var b strings.Builder
88	
89		// Error message
90		if m.err != nil {
91			b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError).Render("Error: "+m.err.Error()) + "\n\n")
92		}
93	
94		left := m.formLeftColumn()
95		right := m.formRightColumn()
96	
97		// Combine left and right columns line-by-line
98		leftWidth := max(m.width/2-2, 40) // -2 for outer padding
99		totalLines := max(len(left), len(right))
100		for i := range totalLines {
101			l := ""
102			if i < len(left) {
103				l = left[i]
104			}
105			r := ""
106			if i < len(right) {
107				r = right[i]
108			}
109			b.WriteString(theme.PadWithBg(l, leftWidth) + theme.Bg("    ") + r + "\n")
110		}
111	
112		// Start button below both columns
113		b.WriteString("\n")
114		b.WriteString(" " + m.renderStartButton())
115	
116		return lipgloss.NewStyle().
117			Padding(1).
118			Background(theme.ColorBackground).
119			Render(b.String())
120	}
121	
122	// renderAdvancedTextInput renders a text input field for advanced options
123	func (m Model) renderAdvancedTextInput(label string, input textinput.Model, fieldIdx int) string {
124		highlightStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorHighlight).Bold(true)
125		if m.focusedField == fieldIdx {
126			return highlightStyle.Render(theme.IconCircleSmall+" "+label+theme.IconChevronRight+" ") + input.View()
127		}
128		return theme.Bg("  "+label+theme.IconChevronRight+" ") + input.View()
129	}
130	
131	// renderTargetTypeField renders target type selection
132	func (m Model) renderTargetTypeField() string {
133		label := "Target Type " + theme.IconSelect + " "
134		textStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText)
135		value := textStyle.Render(m.targetType)
136	
137		highlightStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorHighlight).Bold(true)
138		if m.focusedField == 0 {
139			return highlightStyle.Render(theme.IconCircleSmall+" "+label+theme.IconChevronRight+" ") + value
140		}
141		return theme.Bg("  "+label+theme.IconChevronRight+" ") + value
142	}
143	
144	// renderTargetPathField renders target path input
145	func (m Model) renderTargetPathField() string {
146		label := "Target "
147		highlightStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorHighlight).Bold(true)
148		if m.focusedField == 1 {
149			return highlightStyle.Render(theme.IconCircleSmall+" "+label+theme.IconChevronRight+" ") + m.targetInput.View()
150		}
151		return theme.Bg("  "+label+theme.IconChevronRight+" ") + m.targetInput.View()
152	}
153	
154	// renderCheckbox renders a checkbox. When the field is incompatible with Trivy server mode
155	// and a server is configured, it renders as a locked/disabled option.
156	func (m Model) renderCheckbox(checked bool, label string, fieldIdx int) string {
157		if m.isServerMode() && m.isServerIncompatibleField(fieldIdx) {
158			return theme.RenderCheckboxDisabled(label)
159		}
160		return theme.RenderCheckbox(checked, label, m.focusedField == fieldIdx)
161	}
162	
163	// renderStartButton renders the start scan button
164	func (m Model) renderStartButton() string {
165		canStart := m.deps.TrivyAvailable || m.deps.GitleaksAvailable
166		if !canStart {
167			return theme.DimStyle.Render("[ No scanners available ]")
168		}
169		return " " + theme.RenderButton("Start Scan", m.focusedField == 12, "primary")
170	}
171	
172	// renderScanningView renders the scanning progress with per-stage status rows.
173	func (m Model) renderScanningView() string {
174		elapsed := time.Since(m.scanStartTime).Round(time.Second)
175	
176		var b strings.Builder
177		b.WriteString(theme.DimStyle.Render(fmt.Sprintf("Scanning %s — elapsed: %s", m.targetPath, elapsed)))
178		b.WriteString("\n\n")
179	
180		if len(m.scanStages) == 0 {
181			b.WriteString(theme.SpinnerMessage(m.spinner.View(), "Initializing..."))
182			b.WriteString("\n")
183		} else {
184			for _, stage := range m.scanStages {
185				b.WriteString(m.renderScanStageRow(stage))
186				b.WriteString("\n")
187			}
188		}
189	
190		b.WriteString("\n")
191		b.WriteString(theme.HelpStyle.Render("[esc] cancel scan"))
192	
193		return lipgloss.NewStyle().
194			Background(theme.ColorBackground).
195			Padding(1).
196			Render(b.String())
197	}
198	
199	// renderScanStageRow renders a single stage row with icon, label, and optional detail.
200	// Each segment uses theme.Bg() for gaps to avoid black backgrounds (Rule 115).
201	// The icon column is fixed at width 2 to align spinner (1 cell) with Nerd Font icons (2 cells).
202	func (m Model) renderScanStageRow(stage scan.ProgressUpdate) string {
203		var iconContent string
204		switch stage.Status {
205		case scan.StageDone:
206			iconContent = theme.StatusOKStyle.Render(theme.IconOK) + theme.Bg(" ") // match spinner's built-in trailing space
207		case scan.StageError:
208			iconContent = theme.StatusErrorStyle.Render(theme.IconError) + theme.Bg(" ") // match spinner's built-in trailing space
209		default: // StageRunning
210			iconContent = m.spinner.View() // spinner frames (e.g. "⡿ ") already include a trailing space
211		}
212	
213		labelStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Width(20)
214		label := labelStyle.Render(stage.Label)
215	
216		row := theme.Bg("  ") + iconContent + theme.Bg("  ") + label
217		if stage.Detail != "" {
218			row += theme.Bg("  ") + theme.DimStyle.Render(truncateScanDetail(stage.Detail))
219		}
220		return row
221	}
222	
223	// truncateScanDetail extracts the most meaningful part of a trivy/gitleaks stderr line
224	// and truncates it to fit on one line.
225	func truncateScanDetail(line string) string {
226		// Try to extract the message from a structured log line (timestamp + level + msg)
227		// Format: "2006-01-02T... LEVEL  message"
228		if len(line) > 10 && line[4] == '-' && line[7] == '-' {
229			// Skip timestamp
230			rest := line
231			if idx := strings.IndexAny(rest, " \t"); idx >= 0 {
232				rest = strings.TrimLeft(rest[idx:], " \t")
233				// Skip level
234				if idx2 := strings.IndexAny(rest, " \t"); idx2 >= 0 {
235					msg := strings.TrimLeft(rest[idx2:], " \t")
236					if msg != "" {
237						line = msg
238					}
239				}
240			}
241		}
242		// Skip download progress bar lines
243		if strings.Contains(line, " MiB /") || strings.Contains(line, " p/s ") {
244			return ""
245		}
246		// Skip all trivy component log messages (e.g. "[vuln] ...", "[checks-client] ...")
247		if strings.HasPrefix(line, "[") {
248			return ""
249		}
250		const maxLen = 55
251		if len(line) > maxLen {
252			return line[:maxLen-3] + "..."
253		}
254		return line
255	}
256	
257	// renderResultsView renders the results summary
258	func (m Model) renderResultsView() string {
259		if m.result == nil {
260			return "No results"
261		}
262	
263		var b strings.Builder
264	
265		// Warnings replace the table and hide the tab bar (no partial results to browse)
266		if len(m.result.Errors) > 0 {
267			b.WriteString(m.renderWarningsPanel())
268			if m.statusMessage != "" {
269				b.WriteString("\n")
270				b.WriteString(theme.StatusOKStyle.Render(m.statusMessage))
271			}
272			return b.String()
273		}
274	
275		b.WriteString(m.findingsTable.View())
276	
277		return b.String()
278	}
279	
280	// GetFooterHeight returns the footer height for this view (Rule 124).
281	func (m Model) GetFooterHeight() int {
282		if m.state == StateResults && m.result != nil && len(m.result.Errors) == 0 {
283			return 3 // tab bar + empty line + info line
284		}
285		return 2 // empty line + info line
286	}
287	
288	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
289	func (m Model) RenderFooter(width int) string {
290		if m.state == StateResults && m.result != nil && len(m.result.Errors) == 0 {
291			infoLine := theme.EmptyLineBg(width)
292			if m.statusMessage != "" {
293				infoLine = theme.PadWithBg(theme.StatusOKStyle.Render(m.statusMessage), width)
294			}
295			return theme.PadWithBg(theme.Bg(" ")+m.renderTabs(), width) + "\n" + theme.EmptyLineBg(width) + "\n" + infoLine
296		}
297		infoLine := theme.EmptyLineBg(width)
298		if m.state == StateDetails && m.statusMessage != "" {
299			infoLine = theme.PadWithBg(theme.StatusOKStyle.Render(m.statusMessage), width)
300		}
301		return theme.EmptyLineBg(width) + "\n" + infoLine
302	}
303	
304	// renderTabs renders the tab bar
305	func (m Model) renderTabs() string {
306		cve, secrets, licenses, misconfigs := m.countFindingsByTab()
307	
308		return theme.RenderTabs([]theme.TabItem{
309			{Label: fmt.Sprintf("CVE (%d)", cve)},
310			{Label: fmt.Sprintf("Secrets (%d)", secrets)},
311			{Label: fmt.Sprintf("Licenses (%d)", licenses)},
312			{Label: fmt.Sprintf("Misconfig (%d)", misconfigs)},
313		}, m.activeTab)
314	}
