1	package security
2	
3	import (
4		"context"
5		"fmt"
6		"time"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	
10		"github.com/anthnel/devdesk/internal/cache"
11		"github.com/anthnel/devdesk/internal/config"
12		"github.com/anthnel/devdesk/internal/scan"
13		ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
14		"github.com/anthnel/devdesk/internal/ui/workspaces"
15	)
16	
17	// startScan initiates the security scan.
18	// If returnToOCIImages is set, it sends configured options back to OCI images view instead.
19	func (m Model) startScan() (tea.Model, tea.Cmd) {
20		if m.targetPath == "" {
21			m.err = fmt.Errorf("target path is required")
22			return m, nil
23		}
24		// Trivy fails the whole scan on an address it cannot parse, and the field is
25		// one stray ":" away from holding one. Refusing here says so while the user
26		// is still looking at the field.
27		if err := scan.ValidateTrivyServer(m.trivyServerInput.Value()); err != nil {
28			m.err = err
29			return m, nil
30		}
31	
32		// Persist first, then read back through the one builder. The form used to
33		// assemble the options itself, which is how it ended up being the only one
34		// of three call sites that set IgnoreEOL (D26). Saving first keeps the
35		// behaviour identical — every toggle already writes to the config — while
36		// leaving a single definition of what a configured scan is.
37		m.saveOptionsToConfig()
38		opts := scan.OptionsFromConfig(m.config.Scan)
39	
40		// When opened from OCI images view, delegate scan execution back to that view
41		if m.isImageScan && m.returnToOCIImages {
42			if m.targetPath == "all" {
43				capturedOpts := opts
44				return m, func() tea.Msg { return ociresources.LaunchBatchScanMsg{Opts: capturedOpts} }
45			}
46			capturedOpts := opts
47			capturedName := m.targetPath
48			return m, func() tea.Msg {
49				return ociresources.LaunchSingleImageScanMsg{ImageName: capturedName, Opts: capturedOpts}
50			}
51		}
52	
53		m.state = StateScanning
54		m.err = nil
55		m.scanGen++
56		m.scanStartTime = time.Now()
57		m.scanStages = nil
58	
59		ctx, cancel := context.WithCancel(context.Background())
60		m.cancelScan = cancel
61	
62		ch := make(chan scan.ProgressUpdate, 32)
63		m.progressCh = ch
64		gen := m.scanGen
65		targetPath := m.targetPath
66		targetType := m.getTargetType()
67		opts.OnProgress = func(update scan.ProgressUpdate) {
68			select {
69			case ch <- update:
70			default: // don't block if buffer full
71			}
72		}
73	
74		return m, tea.Batch(
75			m.spinner.Tick,
76			purgeScanCacheCmd(targetPath, targetType),
77			waitForProgressCmd(ch),
78			func() tea.Msg {
79				defer cancel()
80				defer close(ch)
81				scanner := scan.NewScanner(opts)
82				result, err := scanner.Scan(ctx, targetPath, targetType)
83				return ScanCompleteMsg{Result: result, Error: err, Gen: gen}
84			},
85		)
86	}
87	
88	// waitForProgressCmd returns a Cmd that blocks until the next ProgressUpdate is available on ch.
89	// Returns nil when the channel is closed (scan complete).
90	func waitForProgressCmd(ch <-chan scan.ProgressUpdate) tea.Cmd {
91		if ch == nil {
92			return nil
93		}
94		return func() tea.Msg {
95			update, ok := <-ch
96			if !ok {
97				return nil // channel closed, scan finished
98			}
99			return ScanProgressMsg{Update: update}
100		}
101	}
102	
103	// purgeScanCacheCmd deletes the existing cache entries for the target before re-scanning,
104	// so that stale results don't persist if the scan is interrupted or fails.
105	// For workspace (directory) targets, both the counts cache and the full result file are removed.
106	func purgeScanCacheCmd(target string, targetType scan.TargetType) tea.Cmd {
107		return func() tea.Msg {
108			switch targetType {
109			case scan.TargetDirectory:
110				if c, err := cache.NewWorkspaceScanCache(config.CurrentContextName()); err == nil {
111					_ = c.Delete(target)
112				}
113				_ = cache.DeleteWorkspaceScanResult(target)
114			case scan.TargetImage:
115				if c, err := cache.NewImageScanCache(config.CurrentContextName()); err == nil {
116					_ = c.Delete(target)
117				}
118			}
119			return nil
120		}
121	}
122	
123	// getTargetType converts string to TargetType
124	func (m Model) getTargetType() scan.TargetType {
125		switch m.targetType {
126		case "image":
127			return scan.TargetImage
128		default:
129			return scan.TargetDirectory
130		}
131	}
132	
133	// cancelCurrentScan cancels the running scan and returns to StateInput.
134	// The goroutine will still complete and send ScanCompleteMsg, but it will be
135	// discarded because scanGen is incremented here.
136	func (m Model) cancelCurrentScan() (tea.Model, tea.Cmd) {
137		if m.cancelScan != nil {
138			m.cancelScan()
139			m.cancelScan = nil
140		}
141		m.scanGen++ // invalidate any pending ScanCompleteMsg from the cancelled goroutine
142		m.state = StateInput
143		return m, nil
144	}
145	
146	// handleScanProgress updates the per-stage progress state and schedules the next read.
147	func (m Model) handleScanProgress(msg ScanProgressMsg) (tea.Model, tea.Cmd) {
148		u := msg.Update
149		for i, s := range m.scanStages {
150			if s.Stage == u.Stage {
151				m.scanStages[i] = u
152				return m, waitForProgressCmd(m.progressCh)
153			}
154		}
155		// New stage: append in arrival order
156		m.scanStages = append(m.scanStages, u)
157		return m, waitForProgressCmd(m.progressCh)
158	}
159	
160	// handleScanComplete processes scan results
161	func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
162		if msg.Gen != m.scanGen {
163			return m, nil // stale result from a cancelled scan, discard
164		}
165		if msg.Error != nil {
166			m.err = msg.Error
167			m.state = StateInput
168			return m, nil
169		}
170	
171		m.result = msg.Result
172		m.state = StateResults
173		m.updateFindingsTable()
174	
175		// Cache CVE counts and full result for image scans (Rule 126: Enter loads from cache)
176		if m.targetType == "image" && m.result != nil {
177			result := m.result
178			path := m.targetPath
179			go func() {
180				saveImageScanToCache(path, result)
181				_ = cache.SaveImageScanResult(path, result)
182			}()
183		}
184	
185		// For workspace scans: persist full result and send summary back to workspaces view
186		if !m.isImageScan && m.returnToWorkspaces && m.result != nil {
187			result := m.result
188			path := m.targetPath
189			go func() { _ = cache.SaveWorkspaceScanResult(path, result) }()
190			sensitive := hasScanSource(result, "gitleaks")
191			return m, func() tea.Msg {
192				return workspaces.WorkspaceScanCompleteMsg{
193					RepoPath:  path,
194					Critical:  result.Counts.Critical,
195					High:      result.Counts.High,
196					Medium:    result.Counts.Medium,
197					Low:       result.Counts.Low,
198					Sensitive: sensitive,
199					ScannedAt: result.EndTime,
200				}
201			}
202		}
203	
204		return m, nil
205	}
206	
207	// hasScanSource returns true if any finding in the result comes from the given source
208	func hasScanSource(result *scan.Result, source string) bool {
209		for _, f := range result.Findings {
210			if f.Source == source {
211				return true
212			}
213		}
214		return false
215	}
216	
217	// saveImageScanToCache persists CVE severity counts to the image scan cache
218	func saveImageScanToCache(imageName string, result *scan.Result) {
219		c, err := cache.NewImageScanCache(config.CurrentContextName())
220		if err != nil {
221			return
222		}
223		_ = c.Set(imageName, cache.ImageScanEntry{
224			Critical:  result.Counts.Critical,
225			High:      result.Counts.High,
226			Medium:    result.Counts.Medium,
227			Low:       result.Counts.Low,
228			ScannedAt: result.EndTime,
229		})
230	}
