15	func (m Model) GetShortcuts() shortcut.Shortcuts {
16		switch m.state {
17		case StateInput:
18			shortcuts := []shortcut.Shortcut{
19				{Key: "space", Description: "Toggle"},
20				{Key: "←→", Description: "Cycle value"},
21				{Key: "enter / ctrl+s", Description: "Scan"},
22			}
23			// Show 'b' shortcut for directory and image modes on target field
24			if m.focusedField == 1 {
25				shortcuts = append(shortcuts, shortcut.Shortcut{Key: "b", Description: "Browse"})
26			}
27			shortcuts = append(shortcuts,
28				shortcut.Shortcut{Key: "alt+:", Description: "Command"},
29				shortcut.Shortcut{Key: "?", Description: "Help"},
30			)
31			return shortcuts
32		case StateScanning:
33			return []shortcut.Shortcut{
34				// {Key: "scanning...", Description: ""},
35			}
36		case StateResults:
37			shortcuts := []shortcut.Shortcut{
38				{Key: "tab", Description: "Switch tab"},
39				{Key: "enter", Description: "Details"},
40			}
41			if m.activeTab == TabCVE || m.activeTab == TabLicense || m.activeTab == TabMisconfig {
42				shortcuts = append(shortcuts, shortcut.Shortcut{Key: ".", Description: "Filter"})
43			}
44			if m.activeTab == TabSecrets {
45				shortcuts = append(shortcuts, shortcut.Shortcut{Key: "i", Description: "Ignore"})
46			}
47			shortcuts = append(shortcuts,
48				shortcut.Shortcut{Key: "ctrl+r", Description: "New scan"},
49				shortcut.Shortcut{Key: "alt+:", Description: "Command"},
50				shortcut.Shortcut{Key: "?", Description: "Help"},
51			)
52			return shortcuts
53		case StateDetails:
54			shortcuts := []shortcut.Shortcut{
55				{Key: "esc/⌫", Description: "Back"},
56			}
57			if f := m.selectedFinding; f != nil {
58				if len(f.References) > 0 {
59					shortcuts = append(shortcuts, shortcut.Shortcut{Key: "o", Description: "Open ref"})
