163	// parseVersion extracts version number from tool output
164	// versionDisplayWidth caps the fallback version string, which shares a narrow
165	// header column with the tool name.
166	const versionDisplayWidth = 18
167	
168	// looksLikeVersion reports whether a whitespace-separated token is a version
169	// number. A leading "v" only counts when a digit follows it, or the word
170	// "version" in "gitleaks version 8.18.2" would be taken for the version itself.
171	func looksLikeVersion(part string) bool {
172		if part == "" {
173			return false
174		}
175		if part[0] >= '0' && part[0] <= '9' {
176			return true
177		}
178		return part[0] == 'v' && len(part) > 1 && part[1] >= '0' && part[1] <= '9'
179	}
