69	// filterFindingsByTab returns findings filtered by the active tab
70	func (m *Model) filterFindingsByTab() []scan.Finding {
71		if m.result == nil {
72			return nil
73		}
74	
75		var filtered []scan.Finding
76		for _, f := range m.result.Findings {
77			switch m.activeTab {
78			case TabCVE:
79				// CVE: vulnerabilities from trivy (not secrets, not licenses)
80				if f.Source == "trivy" && f.PkgName != "" && f.Match == "" {
81					filtered = append(filtered, f)
82				}
83			case TabSecrets:
84				// Secrets: from gitleaks or trivy secrets
85				if f.Source == "gitleaks" || (f.Source == "trivy" && f.Match != "") {
86					filtered = append(filtered, f)
87				}
88			case TabLicense:
89				// Licenses: from trivy-license source
90				if f.Source == "trivy-license" {
91					filtered = append(filtered, f)
92				}
93			case TabMisconfig:
94				// Misconfigurations: from trivy-misconfig source
95				if f.Source == "trivy-misconfig" {
96					filtered = append(filtered, f)
97				}
98			}
99		}
100		return filtered
101	}
