104	func (m *Model) filterFindingsBySeverity(findings []scan.Finding) []scan.Finding {
105		if m.severityFilter == "all" {
106			return findings
107		}
108	
109		var filtered []scan.Finding
110		for _, f := range findings {
111			switch m.severityFilter {
112			case "critical":
113				if f.Severity == scan.SeverityCritical {
114					filtered = append(filtered, f)
115				}
116			case "high":
117				if f.Severity == scan.SeverityCritical || f.Severity == scan.SeverityHigh {
118					filtered = append(filtered, f)
119				}
120			case "medium":
121				if f.Severity == scan.SeverityCritical || f.Severity == scan.SeverityHigh || f.Severity == scan.SeverityMedium {
122					filtered = append(filtered, f)
123				}
124			case "low":
125				filtered = append(filtered, f)
126			}
127		}
128		return filtered
129	}
