235	func renderShortcutsColumnLines(shortcuts shortcut.Shortcuts, minHeight int) []string {
236		if len(shortcuts) == 0 {
237			return nil
238		}
239	
240		lines := shortcuts.ToStrings()
241	
242		// Find max width for uniform padding
243		maxWidth := 0
244		for _, line := range lines {
245			if w := lipgloss.Width(line); w > maxWidth {
246				maxWidth = w
247			}
248		}
249	
250		// Pad each line to the same width with background
251		var result []string
252		for _, line := range lines {
253			result = append(result, theme.PadWithBg(line, maxWidth))
254		}
255	
256		// Add empty lines if minHeight required
257		for len(result) < minHeight {
258			result = append(result, theme.EmptyLineBg(maxWidth))
259		}
