264	func splitArrayIntoChunks(arr []shortcut.Shortcut, chunkSize int) []shortcut.Shortcuts {
265		var chunks []shortcut.Shortcuts
266		for i := 0; i < len(arr); i += chunkSize {
267			end := i + chunkSize
268			if end > len(arr) {
269				end = len(arr)
270			}
271			chunks = append(chunks, arr[i:end])
272		}
273		return chunks
274	}
