277	func (a *App) renderCommandLineWithCompletion() string {
278		inputView := a.commandInput.View()
279	
280		if len(a.completionSuggestions) == 0 {
281			return inputView
282		}
283	
284		current := a.completionSuggestions[a.completionIndex]
285		currentInput := a.commandInput.Value()
286	
287		previewText := ""
288		if strings.HasPrefix(strings.ToLower(current.Text), strings.ToLower(currentInput)) &&
289			len(currentInput) > 0 {
290			previewText = current.Text[len(currentInput):]
291		}
292	
293		cmdBgStyle := lipgloss.NewStyle().Background(theme.ColorCmdLineBg)
294	
295		preview := cmdBgStyle.Foreground(theme.ColorDim).Render(previewText)
296	
297		hint := cmdBgStyle.Foreground(theme.ColorDim).Italic(true).
298			Render(fmt.Sprintf(" %s [%d/%d]",
299				current.Display,
300				a.completionIndex+1,
301				len(a.completionSuggestions)))
302	
303		contentWidth := lipgloss.Width(inputView) + lipgloss.Width(preview)
304		hintWidth := lipgloss.Width(hint)
305		// width - 2 (outer padding) - 2 (CommandLineStyle inner Padding(0,1,0,1))
306		spacerWidth := (a.width - 4) - contentWidth - hintWidth
307		spacer := ""
308		if spacerWidth > 0 {
309			spacer = cmdBgStyle.Render(strings.Repeat(" ", spacerWidth))
310		}
311	
312		return inputView + preview + spacer + hint
313	}
