32	// and share whatever is left in proportion to their Flex weight. When there is
33	// not enough for everyone, the shortfall comes out of the flexible columns
34	// first and the fixed ones only after — a fixed column is fixed because its
35	// content has a known size, so it is the last thing worth truncating.
36	//
37	// The result always sums to exactly max(available, 0).
38	func solveWidths[T any](columns []Column[T], available int) []int {
39		widths := make([]int, len(columns))
40		if len(columns) == 0 || available <= 0 {
41			return widths
42		}
43	
44		total := 0
45		for i, c := range columns {
46			widths[i] = max(c.MinWidth, 0)
47			total += widths[i]
48		}
49	
50		switch {
51		case total < available:
52			grow(columns, widths, available-total)
53		case total > available:
54			shrink(columns, widths, total-available)
55		}
56		return widths
57	}
