60	// the rounding remainder so the sum is exact. With no flexible column the last
61	// column absorbs it, which is what every view did by hand.
62	func grow[T any](columns []Column[T], widths []int, surplus int) {
63		weight := 0
64		last := -1
65		for i, c := range columns {
